from __future__ import annotations
import argparse
from .common import record, run_purpose

PURPOSE = 'implementation'
CATALOG = [{'id': 'impl-bounded-async-fanout', 'concept': 'bounded-async-fanout', 'domain': 'software-engineering', 'subdomain': 'concurrency-control', 'difficulty': 'intermediate', 'task_type': 'implementation', 'verification_method': 'rubric', 'question': 'A service receives one request that fans out to hundreds of independent downstream calls. Implement a concurrency-control strategy that prevents the fan-out from creating hundreds of simultaneous calls while still allowing useful parallelism.', 'answer': 'Use a bounded semaphore or worker pool around the downstream operation. Each child task must acquire a permit before starting the call and release it in a `finally`/defer-style cleanup path so cancellation or errors cannot leak capacity.\n\nDo not create an unbounded pending queue. Either cap queued work as well or create tasks only when a permit becomes available. Propagate the parent deadline/cancellation signal to children so timed-out work does not continue consuming slots.\n\nThe concurrency limit should come from measured downstream capacity and latency, not from the number of fan-out items. This keeps parallelism useful while bounding memory, sockets, and pressure on the dependency.', 'verification_details': 'Must bound concurrent downstream work, guarantee permit release, propagate cancellation/deadlines, and avoid simply moving the unbounded problem into an unlimited queue.', 'tags': ['fanout', 'semaphore', 'backpressure', 'concurrency']}, {'id': 'impl-versioned-config-snapshot', 'concept': 'versioned-config-snapshot-swap', 'domain': 'software-engineering', 'subdomain': 'configuration', 'difficulty': 'advanced', 'task_type': 'implementation', 'verification_method': 'rubric', 'question': 'Implement live configuration reload for a multithreaded service so readers never observe a half-parsed configuration and a failed reload leaves the previous configuration active.', 'answer': 'Parse and validate the new configuration into a separate immutable snapshot. Do not mutate the active object in place.\n\nAfter validation succeeds, publish the complete snapshot with one synchronized pointer/reference swap. Readers take the current snapshot and use that stable object for the duration of an operation. Reference counting, garbage collection, an RCU-style grace period, or a lock can keep the old snapshot alive until existing readers finish.\n\nIf parsing or validation fails, discard the candidate and keep the current snapshot unchanged. Record the configuration version so logs and requests can identify which snapshot was used.', 'verification_details': 'Must construct and validate a new immutable snapshot before publication, publish atomically, preserve old snapshots for active readers, and retain the previous configuration on reload failure.', 'tags': ['configuration', 'snapshot', 'atomic-publish', 'reload']}, {'id': 'impl-read-exact-loop', 'concept': 'posix-read-exact-loop', 'domain': 'systems-programming', 'subdomain': 'posix-io', 'difficulty': 'intermediate', 'task_type': 'implementation', 'verification_method': 'reference-answer', 'question': 'Implement the logic of a POSIX `read_exact(fd, buf, n)` helper. It should keep reading until `n` bytes arrive, distinguish EOF before completion, and handle interrupted system calls correctly.', 'answer': 'Maintain an offset into the destination buffer and loop until the requested count has been received.\n\nOn each `read()`:\n- if the result is positive, advance the offset by that amount;\n- if it is zero before all bytes are read, report premature EOF;\n- if it returns `-1` with `errno == EINTR`, retry without losing progress;\n- otherwise return the I/O error.\n\nA successful `read()` is allowed to return fewer bytes than requested, so a single call is not sufficient. The implementation must also avoid pointer/count overflow when advancing the buffer for very large requests.', 'verification_details': 'Must handle short reads, EINTR retry, premature EOF, ordinary errors, and preserve partial progress across calls.', 'tags': ['posix', 'read', 'eintr', 'short-read']}, {'id': 'impl-atomic-file-replace', 'concept': 'durable-atomic-file-replacement', 'domain': 'systems-programming', 'subdomain': 'crash-consistency', 'difficulty': 'expert', 'task_type': 'implementation', 'verification_method': 'rubric', 'question': 'Implement a durable configuration-file update on a POSIX filesystem so a crash should leave either the old complete file or the new complete file rather than a partially overwritten file.', 'answer': "Write the new contents to a temporary file in the same directory/filesystem as the target. Check every write, flush the file data with `fsync()` (or the platform's required durability primitive), set required metadata, then atomically `rename()` the temporary pathname over the target.\n\nFor crash durability of the directory entry, `fsync()` the containing directory after the rename on filesystems/platforms where that is required.\n\nThe temporary file must be created safely to avoid pathname races, and cleanup should remove it after failed updates. Writing directly into the existing target is not equivalent because a crash can expose a partially updated file. Cross-filesystem rename must also be avoided because it is not the same atomic operation.", 'verification_details': 'Must use a same-filesystem temporary file, complete/check writes, fsync the file before rename, atomically rename over the target, and account for directory durability.', 'tags': ['fsync', 'rename', 'crash-consistency', 'atomic-update']}, {'id': 'impl-futex-expected-value', 'concept': 'futex-expected-value-wait-loop', 'domain': 'operating-systems', 'subdomain': 'synchronization', 'difficulty': 'expert', 'task_type': 'implementation', 'verification_method': 'rubric', 'question': 'Implement the core wait protocol for a futex-style condition represented by an integer state word. The waiter must not sleep if the state already changed between its userspace check and the kernel wait.', 'answer': 'Read the state and decide whether waiting is still necessary. Pass the observed value as the expected value to the futex wait operation.\n\nThe kernel-side wait must recheck that the word still equals the expected value before sleeping. If it no longer matches, return immediately (commonly as an `EAGAIN`-style result) and re-evaluate the predicate.\n\nAfter any wakeup, loop and recheck the real condition because wakeups can be spurious or another waiter may consume the state transition. The updating path first changes the shared state with the required memory ordering and then issues a wake when waiters may be present.\n\nThe expected-value check closes the classic check-then-sleep lost-wakeup window.', 'verification_details': 'Must use the observed state as the futex expected value, recheck the predicate after immediate return/wakeup, and update state before wake with appropriate synchronization.', 'tags': ['futex', 'lost-wakeup', 'synchronization', 'wait-loop']}, {'id': 'impl-seqlock-reader', 'concept': 'seqlock-reader-retry-protocol', 'domain': 'computer-architecture', 'subdomain': 'concurrency', 'difficulty': 'advanced', 'task_type': 'implementation', 'verification_method': 'rubric', 'question': 'Implement the reader side of a sequence-lock style structure used for a small read-mostly statistics snapshot. Readers must reject a snapshot that overlaps a writer update.', 'answer': 'Read the sequence value before copying the fields. If the value is odd, a writer is active, so retry.\n\nCopy the data using the memory-ordering rules required by the implementation, then read the sequence again. Accept the snapshot only when the two sequence reads are equal and even; otherwise retry from the beginning.\n\nThe writer increments the sequence to an odd value before modifying the fields and to the next even value after publishing the completed update.\n\nThis gives readers a consistent retryable snapshot, not mutual exclusion. It is appropriate only when readers can safely retry and the copied data does not contain objects whose lifetime can disappear during the read.', 'verification_details': 'Must require equal even sequence values before/after the copy, retry on odd or changed sequence, and state the lifetime/retry limitation.', 'tags': ['seqlock', 'memory-ordering', 'read-mostly', 'snapshot']}, {'id': 'impl-pidfd-supervision', 'concept': 'pidfd-child-supervision', 'domain': 'linux-infrastructure', 'subdomain': 'process-supervision', 'difficulty': 'advanced', 'task_type': 'implementation', 'verification_method': 'rubric', 'question': 'Implement child-process supervision on modern Linux without relying on a stored numeric PID that might later be reused for an unrelated process.', 'answer': 'After creating or discovering the child, obtain a pidfd referring to that specific process instance. Keep the pidfd as the stable handle for lifecycle operations rather than treating the numeric PID as an identity token.\n\nIntegrate the pidfd with `poll`/`epoll` or the relevant wait path to detect exit, and use pidfd-based signaling where available. Reap the process with the appropriate wait operation and close the descriptor when supervision ends.\n\nA numeric PID may still be useful for logging, but acting on a stale PID after reuse can target the wrong process. The pidfd remains tied to the original process object.', 'verification_details': 'Must use a pidfd as the process-instance handle, support exit observation/reaping, prefer pidfd-based actions where available, and explain PID-reuse safety.', 'tags': ['linux', 'pidfd', 'supervision', 'pid-reuse']}, {'id': 'impl-wrap-safe-deadline', 'concept': 'wrap-safe-embedded-deadline', 'domain': 'embedded-systems', 'subdomain': 'timers', 'difficulty': 'advanced', 'task_type': 'implementation', 'verification_method': 'reference-answer', 'question': 'A 32-bit millisecond tick counter wraps periodically. Implement a deadline check for delays shorter than half the counter range without breaking when the counter wraps.', 'answer': 'Use modular subtraction rather than ordering the raw counter values.\n\nFor a start time `start` and elapsed duration `delay`, a common pattern is:\n\n```c\nuint32_t elapsed = now - start;\nif (elapsed >= delay) {\n    /* deadline reached */\n}\n```\n\nUnsigned subtraction is defined modulo 2^32, so one wrap is handled naturally. The comparison is unambiguous when the interval being measured is shorter than the modular range constraints used by the design (commonly less than half the range for signed-difference ordering schemes).\n\nDo not write `if (now >= start + delay)` without a wrap-safe convention because the addition and raw ordering can cross the rollover point.', 'verification_details': 'Must use modular elapsed-time arithmetic, explain why raw ordering around wrap is unsafe, and state the interval-range assumption.', 'tags': ['embedded', 'timer', 'wraparound', 'deadline']}, {'id': 'impl-stream-frame-decoder', 'concept': 'incremental-tcp-frame-decoder', 'domain': 'networking', 'subdomain': 'stream-framing', 'difficulty': 'advanced', 'task_type': 'implementation', 'verification_method': 'rubric', 'question': 'Implement the state machine for a length-prefixed protocol over TCP. A single receive can contain half a header, several complete frames, or one complete frame plus part of the next.', 'answer': 'Maintain persistent decoder state across receives: accumulated header bytes, the parsed frame length once available, and accumulated payload bytes.\n\nFeed each received byte range into the state machine. First complete the fixed-size header, validate the decoded length against the protocol maximum, then consume exactly that many payload bytes. Emit a frame only when its full payload is present, reset to header state, and continue processing any bytes remaining in the same receive buffer.\n\nNever assume TCP receive boundaries correspond to message boundaries. Reject invalid lengths before allocating large buffers, and cap buffered incomplete data so a peer cannot force unbounded memory growth.', 'verification_details': 'Must preserve decoder state across receives, support partial/multiple frames, validate lengths before allocation, continue through leftover bytes, and bound incomplete-frame memory.', 'tags': ['tcp', 'framing', 'state-machine', 'stream']}, {'id': 'impl-rendezvous-hashing', 'concept': 'rendezvous-hash-replica-selection', 'domain': 'distributed-systems', 'subdomain': 'partitioning', 'difficulty': 'advanced', 'task_type': 'implementation', 'verification_method': 'rubric', 'question': 'Implement deterministic replica selection using rendezvous hashing for a key and a changing set of storage nodes. The result should be stable across clients that have the same membership view.', 'answer': 'For each candidate node, compute a deterministic hash score from the pair `(key, node_id)` using a stable hash function and encoding. Rank nodes by score and choose the highest-scoring node, or the top `R` distinct nodes when replication is required.\n\nAll clients must use the same node identifiers, hash function, byte encoding, and membership version. Adding or removing a node changes ownership only for keys whose score ranking is affected, avoiding a full reshuffle.\n\nFor weighted capacity, use a mathematically appropriate weighted rendezvous formulation rather than simply duplicating node IDs unless that approximation is explicitly acceptable.', 'verification_details': 'Must score key/node pairs deterministically, select the highest/top-R distinct nodes, require consistent membership/encoding, and explain limited remapping on membership change.', 'tags': ['distributed', 'rendezvous-hashing', 'partitioning', 'replication']}]

FAMILIES = [
    {
        "id": x["id"],
        "concept": x["concept"],
        "domain": x["domain"],
    }
    for x in CATALOG
]

BY_ID = {x["id"]: x for x in CATALOG}

def build(family, rng, rid, _difficulty):
    x = BY_ID[family["id"]]
    return record(
        rid,
        x["domain"],
        x["subdomain"],
        x["task_type"],
        x["difficulty"],
        x["question"],
        x["answer"],
        x["verification_method"],
        x["verification_details"],
        x["tags"],
    )

def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--records", type=int, default=len(FAMILIES))
    ap.add_argument("--seed", type=int, default=20260914)
    args = ap.parse_args()
    run_purpose(
        purpose=PURPOSE,
        families=FAMILIES,
        build=build,
        records_requested=args.records,
        seed=args.seed,
    )

if __name__ == "__main__":
    main()
